// Everything about one kanban board that can be changed: where its cards come
// from, what splits them into columns, what colours them, what the two sides of
// a card show, and the order they sit in.
//
// The dialog edits a draft and hands the whole board back on Save, so nothing
// is written until then and Cancel really does cancel. The suggestions it
// offers - the property names, the column values, the tags - are read off the
// cards the board is showing right now rather than from any list kept for the
// purpose, so a board picks up a property the moment a heading grows one.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Typography from '@mui/joy/Typography';
import Input from '@mui/joy/Input';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Checkbox from '@mui/joy/Checkbox';
import Chip from '@mui/joy/Chip';
import Divider from '@mui/joy/Divider';
import Tooltip from '@mui/joy/Tooltip';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import FormHelperText from '@mui/joy/FormHelperText';
import Autocomplete from '@mui/joy/Autocomplete';
import CircularProgress from '@mui/joy/CircularProgress';
import Alert from '@mui/joy/Alert';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import CloseIcon from '@mui/icons-material/Close';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';

import { ODb, KanbanBoard, KanbanColumn } from '../db';
import {
    Card,
    PALETTE,
    swatch,
    autoSwatch,
    discoverValues,
    propertyNames,
    defaultUnsetTitle,
    colorValueOf,
    boardQuery,
} from '../kanban';

// One circle per palette colour, plus the dashed one that means "whatever the
// value's own spelling works out to" - which is what an unnamed value already
// gets, so choosing it is undoing a choice rather than turning colour off.
function SwatchPicker({ value, onChange, auto, size = 18 }: {
    value: string;
    onChange: (v: string) => void;
    auto?: string;
    size?: number;
}) {
    return (
        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', alignItems: 'center' }}>
            <Tooltip size="sm" title={auto ? `Automatic (${auto})` : 'Automatic'}>
                <Box
                    component="button"
                    type="button"
                    onClick={() => onChange('')}
                    sx={{
                        width: size, height: size, borderRadius: '50%', p: 0, cursor: 'pointer',
                        border: '2px dashed',
                        borderColor: value === '' ? 'background.surface' : 'neutral.400',
                        background: auto ? auto : 'transparent',
                        opacity: value === '' ? 1 : 0.55,
                        // The ring has to read against whatever colour it is
                        // drawn around, so it is the page's own text colour
                        // rather than a fixed hue - a blue ring on the blue
                        // swatch is the one case that cannot be seen at all.
                        outline: value === '' ? '2px solid' : 'none',
                        outlineColor: 'text.primary',
                        outlineOffset: '1px',
                    }}
                />
            </Tooltip>
            {PALETTE.map(s => (
                <Tooltip key={s.key} size="sm" title={s.label}>
                    <Box
                        component="button"
                        type="button"
                        onClick={() => onChange(s.key)}
                        sx={{
                            width: size, height: size, borderRadius: '50%', p: 0, cursor: 'pointer',
                            border: '2px solid',
                            borderColor: value === s.key ? 'background.surface' : 'transparent',
                            background: s.hex,
                            opacity: value === s.key ? 1 : 0.75,
                            outline: value === s.key ? '2px solid' : 'none',
                            outlineColor: 'text.primary',
                            outlineOffset: '1px',
                            transition: 'opacity 0.15s, transform 0.15s',
                            '&:hover': { opacity: 1, transform: 'scale(1.15)' },
                        }}
                    />
                </Tooltip>
            ))}
        </Box>
    );
}

function Section({ title, hint, children }: { title: string; hint?: string; children: React.ReactNode }) {
    return (
        <Box sx={{ mb: 2.5 }}>
            <Typography level="title-sm" sx={{ mb: hint ? 0.25 : 1 }}>{title}</Typography>
            {hint && (
                <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1 }}>{hint}</Typography>
            )}
            {children}
        </Box>
    );
}

export default function KanbanSettings({
    open, board, boards, stored, cards, allTags, onClose, onSave, onDelete, onDuplicate,
}: {
    open: boolean;
    board: KanbanBoard;
    boards: KanbanBoard[];
    stored: { name: string; query: string }[];
    cards: Card[];
    allTags: string[];
    onClose: () => void;
    onSave: (next: KanbanBoard, originalName: string) => void;
    onDelete: (name: string) => void;
    onDuplicate: (b: KanbanBoard) => void;
}) {
    const [draft, setDraft] = React.useState<KanbanBoard>(board);
    const [confirmDelete, setConfirmDelete] = React.useState(false);
    const [count, setCount] = React.useState<number | null>(null);
    const [counting, setCounting] = React.useState(false);

    // The board being edited is the one the dialog opened on, not whatever it
    // was last time: reopening on another board with a stale draft is how you
    // save one board's columns onto another.
    React.useEffect(() => {
        if (open) {
            setDraft(board);
            setConfirmDelete(false);
        }
    }, [open, board]);

    const set = React.useCallback(<K extends keyof KanbanBoard>(key: K, value: KanbanBoard[K]) => {
        setDraft(d => ({ ...d, [key]: value }));
    }, []);

    // How many headings the draft's query finds, so that a board is never saved
    // blind. Debounced, because this runs while the expression is being typed.
    React.useEffect(() => {
        if (!open) return;
        const { query, baseFilter } = boardQuery(draft, stored);
        const controller = new AbortController();
        const timer = setTimeout(() => {
            setCounting(true);
            ODb.query(query, false, controller.signal, baseFilter)
                .then(r => { if (!controller.signal.aborted) { setCount(Array.isArray(r) ? r.length : 0); setCounting(false); } })
                .catch(() => { if (!controller.signal.aborted) { setCount(null); setCounting(false); } });
        }, 400);
        return () => { clearTimeout(timer); controller.abort(); };
    }, [open, draft.query, draft.storedQuery, draft.includeArchived, stored, draft]);

    const props = React.useMemo(() => propertyNames(cards), [cards]);
    const missing = React.useMemo(() => discoverValues(cards, draft), [cards, draft]);

    // Every value that could want a colour: the ones a colour has already been
    // chosen for, and the ones the cards on the board actually carry.
    const colorValues = React.useMemo(() => {
        const out = new Set<string>(Object.keys(draft.colors || {}));
        if (draft.colorBy !== 'none') {
            for (const c of cards) {
                const v = colorValueOf(c, draft);
                if (v !== '') out.add(v);
            }
        }
        return Array.from(out).sort();
    }, [cards, draft]);

    const nameTaken = draft.name.trim() !== '' &&
        draft.name.trim() !== board.name &&
        boards.some(b => b.name === draft.name.trim());

    function setColumn(i: number, patch: Partial<KanbanColumn>) {
        setDraft(d => ({ ...d, columns: d.columns.map((c, j) => (j === i ? { ...c, ...patch } : c)) }));
    }

    function addColumn(value = '') {
        setDraft(d => ({ ...d, columns: [...d.columns, { value, title: '', color: '', limit: 0, collapsed: false }] }));
    }

    function removeColumn(i: number) {
        setDraft(d => ({ ...d, columns: d.columns.filter((_, j) => j !== i) }));
    }

    function moveColumn(i: number, by: number) {
        setDraft(d => {
            const next = d.columns.slice();
            const j = i + by;
            if (j < 0 || j >= next.length) return d;
            const tmp = next[i];
            next[i] = next[j];
            next[j] = tmp;
            return { ...d, columns: next };
        });
    }

    function fillColumns() {
        setDraft(d => ({
            ...d,
            columns: [...d.columns, ...discoverValues(cards, d).map(v => ({
                value: v, title: '', color: '', limit: 0, collapsed: false,
            }))],
        }));
    }

    function setColor(value: string, key: string) {
        setDraft(d => {
            const colors = { ...(d.colors || {}) };
            if (key === '') delete colors[value];
            else colors[value] = key;
            return { ...d, colors };
        });
    }

    const groupHint = draft.groupBy === 'property'
        ? 'A card sits in the column whose value matches its property.'
        : draft.groupBy === 'tag'
            ? 'A card sits in the first column whose tag it carries, so the order of the columns decides where a card with two of them goes.'
            : 'A card sits in the column matching its todo keyword.';

    function save() {
        const name = draft.name.trim();
        if (name === '' || nameTaken) return;
        onSave({ ...draft, name }, board.name);
    }

    return (
        <Modal open={open} onClose={onClose}>
            <ModalDialog
                sx={{
                    width: 'min(880px, 96vw)',
                    maxHeight: '92dvh',
                    display: 'flex',
                    flexDirection: 'column',
                    p: 0,
                    overflow: 'hidden',
                }}
            >
                <Box sx={{ px: 3, pt: 2.5, pb: 1.5 }}>
                    <Typography level="title-lg">Board settings</Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        A board is a way of looking at your org files. Nothing here is written into them.
                    </Typography>
                    <ModalClose />
                </Box>
                <Divider />

                <Box sx={{ px: 3, py: 2, overflowY: 'auto', flex: 1 }}>
                    <Section title="Name">
                        <Input
                            size="sm"
                            value={draft.name}
                            onChange={e => set('name', e.target.value)}
                            error={nameTaken}
                            sx={{ maxWidth: 360 }}
                        />
                        {nameTaken && (
                            <FormHelperText sx={{ color: 'danger.500' }}>Another board already has that name.</FormHelperText>
                        )}
                    </Section>

                    <Section
                        title="Cards"
                        hint="The headings on the board. A saved query keeps the board and the query in step; an expression written here belongs to this board alone."
                    >
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                            <FormControl size="sm" sx={{ minWidth: 220 }}>
                                <FormLabel>Saved query</FormLabel>
                                <Select
                                    size="sm"
                                    value={draft.storedQuery}
                                    onChange={(_, v) => set('storedQuery', (v as string) || '')}
                                    placeholder="None"
                                >
                                    <Option value="">Write one here instead</Option>
                                    {stored.map(s => <Option key={s.name} value={s.name}>{s.name}</Option>)}
                                </Select>
                            </FormControl>
                            <FormControl size="sm" sx={{ flex: 1, minWidth: 260 }}>
                                <FormLabel>Query expression</FormLabel>
                                <Input
                                    size="sm"
                                    value={draft.storedQuery ? (stored.find(s => s.name === draft.storedQuery)?.query || '') : draft.query}
                                    disabled={!!draft.storedQuery}
                                    onChange={e => set('query', e.target.value)}
                                    placeholder={'e.g. HasTags("note") && !IsTodo()'}
                                    sx={{ fontFamily: 'monospace', fontSize: 12 }}
                                />
                            </FormControl>
                        </Box>
                        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mt: 1 }}>
                            <Checkbox
                                size="sm"
                                label="Include archived"
                                checked={draft.includeArchived}
                                onChange={e => set('includeArchived', e.target.checked)}
                            />
                            {counting ? <CircularProgress size="sm" /> : (
                                <Chip size="sm" variant="soft" color={count && count > 0 ? 'success' : 'neutral'}>
                                    {count === null ? 'no answer' : `${count} heading${count === 1 ? '' : 's'}`}
                                </Chip>
                            )}
                        </Box>
                    </Section>

                    <Divider sx={{ my: 2 }} />

                    <Section title="Columns" hint={groupHint}>
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-end', mb: 1.5 }}>
                            <FormControl size="sm" sx={{ minWidth: 160 }}>
                                <FormLabel>Split by</FormLabel>
                                <Select size="sm" value={draft.groupBy} onChange={(_, v) => set('groupBy', (v as KanbanBoard['groupBy']) || 'status')}>
                                    <Option value="property">Property</Option>
                                    <Option value="tag">Tag</Option>
                                    <Option value="status">Todo keyword</Option>
                                </Select>
                            </FormControl>
                            {draft.groupBy === 'property' && (
                                <FormControl size="sm" sx={{ minWidth: 220 }}>
                                    <FormLabel>Property</FormLabel>
                                    <Autocomplete
                                        size="sm"
                                        freeSolo
                                        options={props}
                                        value={draft.groupKey}
                                        onChange={(_, v) => set('groupKey', (v as string) || '')}
                                        onInputChange={(_, v) => set('groupKey', v || '')}
                                        placeholder="STAGE"
                                    />
                                </FormControl>
                            )}
                            <Button size="sm" variant="soft" startDecorator={<AutoAwesomeIcon />} onClick={fillColumns} disabled={missing.length === 0}>
                                {missing.length === 0 ? 'Nothing new to add' : `Add ${missing.length} found in the cards`}
                            </Button>
                            <Button size="sm" variant="plain" startDecorator={<AddIcon />} onClick={() => addColumn()}>
                                Add column
                            </Button>
                        </Box>

                        {draft.columns.length === 0 ? (
                            <Alert size="sm" variant="soft" color="neutral">
                                No columns yet. Add them by hand, or let the board read them off the cards it found.
                            </Alert>
                        ) : (
                            <Sheet variant="outlined" sx={{ borderRadius: 'sm', p: 1 }}>
                                {draft.columns.map((col, i) => {
                                    const auto = autoSwatch(col.value).hex;
                                    return (
                                        <Box
                                            key={i}
                                            sx={{
                                                display: 'flex', gap: 1, alignItems: 'center', py: 0.75,
                                                borderBottom: i < draft.columns.length - 1 ? '1px solid' : 'none',
                                                borderColor: 'divider',
                                                flexWrap: 'wrap',
                                            }}
                                        >
                                            <Box
                                                sx={{
                                                    width: 10, height: 26, borderRadius: 4, flexShrink: 0,
                                                    background: col.color ? swatch(col.color).hex : auto,
                                                }}
                                            />
                                            <Input
                                                size="sm"
                                                placeholder={draft.groupBy === 'tag' ? 'tag' : 'value'}
                                                value={col.value}
                                                onChange={e => setColumn(i, { value: e.target.value })}
                                                sx={{ width: 150, fontFamily: 'monospace', fontSize: 12 }}
                                            />
                                            <Input
                                                size="sm"
                                                placeholder={col.value || 'Title'}
                                                value={col.title}
                                                onChange={e => setColumn(i, { title: e.target.value })}
                                                sx={{ width: 150 }}
                                            />
                                            <Tooltip size="sm" title="Warn above this many cards. 0 is no limit.">
                                                <Input
                                                    size="sm"
                                                    type="number"
                                                    value={col.limit || 0}
                                                    onChange={e => setColumn(i, { limit: Math.max(0, Number(e.target.value) || 0) })}
                                                    startDecorator={<Typography level="body-xs">wip</Typography>}
                                                    slotProps={{ input: { min: 0 } }}
                                                    sx={{ width: 110 }}
                                                />
                                            </Tooltip>
                                            <SwatchPicker value={col.color} auto={auto} onChange={v => setColumn(i, { color: v })} size={15} />
                                            <Box sx={{ ml: 'auto', display: 'flex' }}>
                                                <IconButton size="sm" variant="plain" disabled={i === 0} onClick={() => moveColumn(i, -1)}>
                                                    <ArrowUpwardIcon fontSize="small" />
                                                </IconButton>
                                                <IconButton size="sm" variant="plain" disabled={i === draft.columns.length - 1} onClick={() => moveColumn(i, 1)}>
                                                    <ArrowDownwardIcon fontSize="small" />
                                                </IconButton>
                                                <IconButton size="sm" variant="plain" color="danger" onClick={() => removeColumn(i)}>
                                                    <CloseIcon fontSize="small" />
                                                </IconButton>
                                            </Box>
                                        </Box>
                                    );
                                })}
                            </Sheet>
                        )}

                        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mt: 1.5, flexWrap: 'wrap' }}>
                            <Checkbox
                                size="sm"
                                label="Keep a column for the cards no column claims"
                                checked={draft.showUnset}
                                onChange={e => set('showUnset', e.target.checked)}
                            />
                            {draft.showUnset && (
                                <Input
                                    size="sm"
                                    placeholder={defaultUnsetTitle(draft)}
                                    value={draft.unsetTitle}
                                    onChange={e => set('unsetTitle', e.target.value)}
                                    sx={{ width: 200 }}
                                />
                            )}
                        </Box>
                    </Section>

                    <Divider sx={{ my: 2 }} />

                    <Section
                        title="Colour"
                        hint="What a card's stripe means. A value nobody has picked a colour for is given one from its own spelling, so it keeps that colour everywhere and forever."
                    >
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                            <FormControl size="sm" sx={{ minWidth: 160 }}>
                                <FormLabel>Colour by</FormLabel>
                                <Select size="sm" value={draft.colorBy} onChange={(_, v) => set('colorBy', (v as KanbanBoard['colorBy']) || 'none')}>
                                    <Option value="none">Nothing</Option>
                                    <Option value="property">Property</Option>
                                    <Option value="tag">Tag</Option>
                                    <Option value="status">Todo keyword</Option>
                                    <Option value="priority">Priority</Option>
                                </Select>
                            </FormControl>
                            {draft.colorBy === 'property' && (
                                <FormControl size="sm" sx={{ minWidth: 220 }}>
                                    <FormLabel>Property</FormLabel>
                                    <Autocomplete
                                        size="sm"
                                        freeSolo
                                        options={props}
                                        value={draft.colorKey}
                                        onChange={(_, v) => set('colorKey', (v as string) || '')}
                                        onInputChange={(_, v) => set('colorKey', v || '')}
                                        placeholder="AREA"
                                    />
                                </FormControl>
                            )}
                        </Box>

                        {draft.colorBy !== 'none' && (
                            <Sheet variant="soft" sx={{ borderRadius: 'sm', p: 1.5, mt: 1.5 }}>
                                {colorValues.length === 0 ? (
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                        None of the cards on the board carry that yet.
                                    </Typography>
                                ) : colorValues.map(v => (
                                    <Box key={v} sx={{ display: 'flex', gap: 1.5, alignItems: 'center', mb: 0.75, flexWrap: 'wrap' }}>
                                        <Typography level="body-sm" sx={{ width: 160, fontFamily: 'monospace', fontSize: 12 }} noWrap title={v}>
                                            {v}
                                        </Typography>
                                        <SwatchPicker
                                            value={(draft.colors || {})[v] || ''}
                                            auto={autoSwatch(v).hex}
                                            onChange={k => setColor(v, k)}
                                            size={15}
                                        />
                                    </Box>
                                ))}
                            </Sheet>
                        )}
                    </Section>

                    <Divider sx={{ my: 2 }} />

                    <Section title="The two sides of a card" hint="The front is what you read at a glance. The back is turned over by a click and fetched only then.">
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                            <FormControl size="sm" sx={{ minWidth: 300, flex: 1 }}>
                                <FormLabel>Front: properties shown as chips</FormLabel>
                                <Autocomplete
                                    size="sm"
                                    multiple
                                    freeSolo
                                    options={props}
                                    value={draft.badges}
                                    onChange={(_, v) => set('badges', (v as string[]) || [])}
                                    placeholder={draft.badges.length === 0 ? 'None' : ''}
                                />
                            </FormControl>
                            <FormControl size="sm" sx={{ minWidth: 200 }}>
                                <FormLabel>Back shows</FormLabel>
                                <Select size="sm" value={draft.backShows} onChange={(_, v) => set('backShows', (v as KanbanBoard['backShows']) || 'both')}>
                                    <Option value="body">The heading's text</Option>
                                    <Option value="properties">Its properties</Option>
                                    <Option value="both">Both</Option>
                                </Select>
                            </FormControl>
                        </Box>
                    </Section>

                    <Section title="Order within a column">
                        <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                            <FormControl size="sm" sx={{ minWidth: 180 }}>
                                <FormLabel>Sort</FormLabel>
                                <Select size="sm" value={draft.sort} onChange={(_, v) => set('sort', (v as KanbanBoard['sort']) || 'manual')}>
                                    <Option value="manual">By hand</Option>
                                    <Option value="headline">Headline</Option>
                                    <Option value="priority">Priority</Option>
                                    <Option value="deadline">Deadline</Option>
                                    <Option value="scheduled">Scheduled</Option>
                                    <Option value="file">File</Option>
                                </Select>
                            </FormControl>
                            {draft.sort === 'manual' && (
                                <FormControl size="sm" sx={{ minWidth: 200 }}>
                                    <FormLabel>Written to property</FormLabel>
                                    <Input
                                        size="sm"
                                        value={draft.orderKey}
                                        onChange={e => set('orderKey', e.target.value.toUpperCase())}
                                        placeholder="KANBAN"
                                        sx={{ fontFamily: 'monospace', fontSize: 12 }}
                                    />
                                    <FormHelperText>
                                        Dragging a card up or down writes this one number on it, and nothing else.
                                    </FormHelperText>
                                </FormControl>
                            )}
                        </Box>
                    </Section>

                    {draft.groupBy === 'tag' && allTags.length > 0 && (
                        <Section title="Tags on the server" hint="Every tag the server knows about, for reference while filling in the columns.">
                            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', maxHeight: 88, overflowY: 'auto' }}>
                                {allTags.map(t => (
                                    <Chip
                                        key={t}
                                        size="sm"
                                        variant="outlined"
                                        onClick={() => addColumn(t)}
                                        sx={{ cursor: 'pointer' }}
                                    >
                                        {t}
                                    </Chip>
                                ))}
                            </Box>
                        </Section>
                    )}
                </Box>

                <Divider />
                <Box sx={{ px: 3, py: 2, display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
                    <Button
                        size="sm"
                        variant={confirmDelete ? 'solid' : 'soft'}
                        color="danger"
                        startDecorator={<DeleteIcon />}
                        onClick={() => { if (confirmDelete) onDelete(board.name); else setConfirmDelete(true); }}
                    >
                        {confirmDelete ? 'Really delete this board' : 'Delete board'}
                    </Button>
                    <Button size="sm" variant="soft" color="neutral" startDecorator={<ContentCopyIcon />} onClick={() => onDuplicate(draft)}>
                        Duplicate
                    </Button>
                    <Box sx={{ ml: 'auto', display: 'flex', gap: 1 }}>
                        <Button size="sm" variant="plain" color="neutral" onClick={onClose}>Cancel</Button>
                        <Button size="sm" onClick={save} disabled={draft.name.trim() === '' || nameTaken}>Save board</Button>
                    </Box>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
